local NEAR = 150 * 150
local function Name(id)
	local n = (C_Item and C_Item.GetItemNameByID and C_Item.GetItemNameByID(id)) or (GetItemInfo and GetItemInfo(id))
	if n and not (issecretvalue and issecretvalue(n)) then return n end
end
local named = {}
local f = CreateFrame("Frame")
f:RegisterEvent("PLAYER_LOGIN")
f:RegisterEvent("GET_ITEM_INFO_RECEIVED")
f:SetScript("OnEvent", function(_, ev, item)
	local D = _G.PintsRareData
	if not (D and D.rares and D.items) then return end
	if ev == "GET_ITEM_INFO_RECEIVED" then
		if item and named[item] == false then local n = Name(item); if n then D.items[item][1] = n; named[item] = true end end
		return
	end
	if not NS.MapToWorld then return end
	local moved, added = 0, 0
	for id, a in pairs(FIX) do
		local r = D.rares[id]
		if r then
			if a[1] then r[3], r[4] = a[1], a[2] or a[1] end
			-- spots
			local fw = {}
			for k = 1, #a[3], 3 do
				local c, x, y = NS.MapToWorld(a[3][k], a[3][k + 1], a[3][k + 2])
				if c and x then fw[#fw + 1] = { c, x, y } end
			end
			if #fw > 0 then
				local old, keep, near = r[7] or {}, {}, {}
				for k = 1, #old, 3 do
					local hit = false
					for n, p in ipairs(fw) do
						if p[1] == old[k] and (p[2] - old[k + 1]) ^ 2 + (p[3] - old[k + 2]) ^ 2 <= NEAR then hit = true; near[n] = true end
					end
					if hit then keep[#keep + 1] = old[k]; keep[#keep + 1] = old[k + 1]; keep[#keep + 1] = old[k + 2] end
				end
				if #keep == 0 then moved = moved + 1 end
				for n, p in ipairs(fw) do
					if not near[n] then
						local dup = false
						for k = 1, #keep, 3 do
							if keep[k] == p[1] and (keep[k + 1] - p[2]) ^ 2 + (keep[k + 2] - p[3]) ^ 2 <= NEAR then dup = true break end
						end
						if not dup then keep[#keep + 1] = p[1]; keep[#keep + 1] = p[2]; keep[#keep + 1] = p[3]; added = added + 1 end
					end
				end
				r[7] = keep
			end
			-- drops
			if #a[4] > 0 then
				local loot = {}
				for k = 1, #a[4], 3 do
					local item = a[4][k]
					loot[#loot + 1] = item; loot[#loot + 1] = a[4][k + 1]
					if not D.items[item] then
						local n = Name(item)
						D.items[item] = { n or ("item " .. item), a[4][k + 2] }
						named[item] = n and true or false
						if not n and C_Item and C_Item.RequestLoadItemDataByID then C_Item.RequestLoadItemDataByID(item) end
					end
				end
				r[8] = loot
			end
		end
	end
	NS.ForeverRareFix = { moved = moved, added = added }
end)
